        // We want the largest s1 such that s1 < m - s2
        long long target = m - s2;
        // Find the largest element in sums1 that is < target
        auto it = lower_bound(sums1.begin(), sums1.end(), target);
        if (it != sums1.begin()) {
            it--;
            long long candidate = (*it + s2) % m;
