        // But actually, we want s1+s2 to be just above m to get a value close to m-1.
        // So we want the smallest s1 such that s1 >= m - s2.

        auto it2 = lower_bound(sums1.begin(), sums1.end(), m - s2);
        if (it2 != sums1.end()) {
